/*
 * A128217  Nonnegative integers n such that the square-root of n differs from
 *          its nearest integer by less than 1/4.
 * https://oeis.org/A128217
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = set of nonnegative integers n such that the distance
 *            between sqrt(n) and its nearest integer is less than 1/4. The
 *            values are generated by iterating over integer k and taking the
 *            two disjoint intervals around k^2 and (k+1)^2
 * Range:     u8 n <= 128, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    /* Guard against out‑of‑range n; the sequence is defined for n >= 1. */
    if (n < 1)
        return (seq_t)0;

    idx_t rem = n;            /* remaining index within current block */
    idx_t k   = 0;            /* current integer k */

    while (1) {
        /* Count in the first interval [k^2, floor((k+0.25)^2)] */
        idx_t count1 = (k >> 1) + (idx_t)1;          /* k/2 + 1 */

        /* floor(1.5k + 0.5625) = (3k)/2 + (k mod 2) */
        idx_t floor_1p5k = ((3 * k) >> 1) + (k & 1);

        /* Count in the second interval [floor((k+0.75)^2)+1, (k+1)^2-1] */
        idx_t count2 = (2 * k) - floor_1p5k;         /* 2k - floor(1.5k+0.5625) */

        idx_t count_k = count1 + count2;            /* total numbers in block k */

        if (rem <= count_k) {
            /* The required term is inside block k */
            if (rem <= count1) {
                /* First interval: offset from k^2 */
                idx_t offset = rem - (idx_t)1;
                return (seq_t)k * (seq_t)k + (seq_t)offset;
            } else {
                /* Second interval: offset from its lower bound */
                idx_t offset = rem - count1 - (idx_t)1;
                seq_t low2 = (seq_t)k * (seq_t)k
                                 + (seq_t)floor_1p5k
                                 + (seq_t)1;
                return low2 + (seq_t)offset;
            }
        }

        /* Move to the next block */
        rem -= count_k;
        ++k;
    }
}
